from solution import get_max_triples
import math
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def brute_reference(n):
    """Obviously-correct brute force directly from spec."""
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count


def residue_reference(n):
    """Independent model: a[i] mod 3 is 0 iff i%3==2 else 1, so only
    homogeneous triples count."""
    c0 = sum(1 for i in range(1, n + 1) if i % 3 == 2)
    c1 = n - c0
    return math.comb(c0, 3) + math.comb(c1, 3) if n >= 3 else 0


def test_example_n_equals_5():
    assert get_max_triples(5) == 1


def test_array_definition_for_example():
    # Spec defines a[i] = i*i - i + 1; for n=5 this is [1,3,7,13,21]
    # and only (1,7,13) sums to multiple of 3.
    a = [i * i - i + 1 for i in range(1, 6)]
    assert a == [1, 3, 7, 13, 21]
    assert get_max_triples(5) == brute_reference(5) == 1


def test_no_triples_when_n_less_than_3():
    assert get_max_triples(1) == 0
    assert get_max_triples(2) == 0


def test_returns_int_not_bool_for_small_n():
    for n in [1, 2, 3]:
        r = get_max_triples(n)
        assert type(r) is int, f"n={n} returned {r!r} of type {type(r)}"
        assert isinstance(r, int) and not isinstance(r, bool)


def test_returns_int_type():
    for n in [1, 2, 3, 4, 5, 10, 30]:
        r = get_max_triples(n)
        assert type(r) is int


def test_exact_small_values():
    # Verified by hand / brute force from spec definition.
    expected = {
        1: 0,
        2: 0,
        3: 0,
        4: 1,
        5: 1,
        6: 4,
        7: 10,
        8: 11,
        9: 12,
        10: 22,
    }
    for n, v in expected.items():
        assert get_max_triples(n) == v, f"n={n}"
        assert brute_reference(n) == v, f"reference check n={n}"


def test_residue_values_never_two():
    # Spec property: i*i - i + 1 mod 3 is never 2.
    for i in range(1, 50):
        assert (i * i - i + 1) % 3 in (0, 1)


@given(st.integers(min_value=1, max_value=30))
def test_brute_force_equivalence(n):
    assert get_max_triples(n) == brute_reference(n)


@given(st.integers(min_value=1, max_value=100))
def test_residue_model_equivalence(n):
    assert get_max_triples(n) == residue_reference(n)


@given(st.integers(min_value=1, max_value=100))
def test_within_combinatorial_bounds(n):
    r = get_max_triples(n)
    assert 0 <= r <= math.comb(n, 3) if n >= 3 else r == 0


@given(st.integers(min_value=1, max_value=99))
def test_monotonic_non_decreasing(n):
    assert get_max_triples(n + 1) >= get_max_triples(n)


@given(st.integers(min_value=1, max_value=50))
def test_increment_equals_new_triples_ending_at_end(n):
    # Triples for n+1 = triples for n + pairs (i<j<=n) completing a valid triple.
    a = [i * i - i + 1 for i in range(1, n + 2)]
    last = a[-1]
    added = sum(
        1
        for i in range(n)
        for j in range(i + 1, n)
        if (a[i] + a[j] + last) % 3 == 0
    )
    assert get_max_triples(n + 1) == get_max_triples(n) + added


@given(st.integers(min_value=3, max_value=100))
def test_homogeneous_residue_decomposition(n):
    # Since only residues 0/1 occur, result must equal C(c0,3)+C(c1,3).
    c0 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 0)
    c1 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 1)
    assert c0 + c1 == n
    assert get_max_triples(n) == math.comb(c0, 3) + math.comb(c1, 3)
